Q["Deprecated: Offensive Channeling"] = { v = { { k="thefacetofkeannastoredinsidekeannaswillw", t="Хуучирсан: Довтолгооны чиглүүлэлт", d="Довтолгооны ид шид бол миний мэргэжил байсан... үүнийг л би санаж чадаж байна. Би өөрийн arcane чиглүүлэх хүчээ чинийхэд нэмж чадах бүхнээ хийнэ.$B$BГэхдээ надад одоо байгаагаас илүү түүхий хүч хэрэгтэй. Guardian's Library-ийн дээд давхраар тэнүүчилж буй arcane anomaly-ууд маш сайн бай болох болно. Тэдний arcane residue-г цуглуул, бидэнд маш их хэрэгтэй.", o="Keanna's Will дотор хадгалагдсан Facet of Keanna таныг Karazhan дахь Arcane Anomaly-аас 20 Arcane Residue цуглуулахыг хүсч байна." } } }
Q["Deprecated: Physical Enhancement"] = { v = { { k="iwouldntmindthatwemightaswellmakethebest", t="Хуучирсан: Бие бялдрын сайжруулалт", d="Би үүнийг эсэргүүцэхгүй. Бидэнд байгаа нөхцөлөө хамгийн сайнаар ашиглах нь дээр... миний хувьд зэвсэг байх. Тэгвэл чадах бүхнээрээ хамгийн сайн зэвсэг болъё.$B$BТийм ээ, хийцгээе. Илүү хурц ир, илүү бат бөх бариул... сонсоход надад таалагдаж байна.$B$BНадад хэдэн зүйл цуглуулж өгөх хэрэгтэй." } } }
Q["Deprecated: Reforge a Long Blade"] = { t="Deprecated: Урт ирийг дахин хийх", d="Энэ зэвсэг маш олон хэсэгт хуваагдсан... буцааж угсрах нь амаргүй байх болно.$B$BБи khorium хэрэгтэй. Их хэмжээгээр. Бас void crystal болон primal fire хэрэгтэй.", o="40 Khorium Bar, 1 Void Crystal болон 8 Primal Fire-ыг Karazhan дотор Koren-д авчир." }
